/** Decode `bytes` as the named contract type and re-encode canonically. */
export function roundtripNamed(typeName: string, bytes: Uint8Array): Uint8Array {
  const codec = REGISTRY[typeName];
  if (!codec) throw new Error(`unknown contract type ${typeName}`);
  return toCanonical(codec[0](codec[1](parse(bytes), "$")));
}
